/**
 * Unit tests for the ThemeVersionChannelAttributeHolder trait.
 *
 * Covers assignment, retrieval, default fallback,
 * transfer between holders, validation rules, and unset operations.
 */
class ThemeVersionChannelAttributeHolderUnitTest extends TestCase
{
    /**
     * Asserts that the code attribute is not assigned by default
     * and that getChannel returns null on a freshly created holder.
     */
    public function testChannelNotAssignedByDefault(): void
    {
        // Arrange
        $holder = new ImplWithThemeVersionChannelAttributeHolderUnitTest();

        // Assert
        $this->assertFalse($holder->isChannelAssigned());
        $this->assertNull($holder->getChannel());
    }
}
